// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// Only one thing moves: a single breath. Radius, rotation and appearance all interpolate between placed keyframes through keyAt.
// Bare lowercase names (holdStart, radiusRest) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const linear = (t) => t; // for segments between equal values — any curve, no movement

// every curve is the same standard as CSS cubic-bezier() — the numbers are yours to choose
const breathOpen  = cubicBezier(...breathOpenHandles);  // the breath opening
const breathClose = cubicBezier(...breathCloseHandles); // the breath closing — its own face
const spinRise    = cubicBezier(...spinRiseHandles);    // rotation, way out
const spinFall    = cubicBezier(...spinFallHandles);    // rotation, way back
const railOut     = cubicBezier(...railOutHandles);     // edge rail, way out
const railBack    = cubicBezier(...railBackHandles);    // edge rail, way back

// the breath — separate curves for opening and closing; equal values hold in between
const breathKeys = [
  { frame: openStart, value: 0, curve: breathOpen },  // the opening starts here
  { frame: holdStart, value: 1, curve: linear },      // fully open — the hold begins
  { frame: holdEnd,   value: 1, curve: breathClose }, // hold over — into the close
  { frame: closeEnd,  value: 0 },                     // closed and resting
];
// the rotation — same frame ranges as the breath, with 2 curves of its own
const spinKeys = [
  { frame: openStart, value: 0,     curve: spinRise },
  { frame: holdStart, value: 1 / 2, curve: linear },  // half the turn by the hold
  { frame: holdEnd,   value: 1 / 2, curve: spinFall },
  { frame: closeEnd,  value: 1 },                     // the other half on the way home
];
// the edge rail — a radius round trip on its own frame ranges
const railKeys = [
  { frame: railStart,     value: railRest, curve: railOut },
  { frame: railHoldStart, value: railPeak, curve: linear },
  { frame: railHoldEnd,   value: railPeak, curve: railBack },
  { frame: railEnd,       value: railRest },
];

const center = { x: stageSize / 2, y: stageSize / 2 }; // center of a square canvas of side stageSize
const rad = (deg) => (deg * Math.PI) / 180; // degrees → radians

// frame number in, position and size of all 19 dots out
function latticeAt(frame) {
  const breath = keyAt(breathKeys, frame);
  const radius = radiusRest + (radiusPeak - radiusRest) * breath; // only the radius rides the breath
  const spin = spinPerLoop * keyAt(spinKeys, frame);
  return dots.map((dot) => ({
    angle: dot.angle + spin,                           // every dot rides the same rotation
    dist: dot.role === "arm"  ? radius                 // base dots — the breath's radius
        : dot.role === "edge" ? keyAt(railKeys, frame) // edge dots — the dedicated rail
        : dot.dist,                                    // center and inner ring — the row's distance
    scale: dot.grow ? keyAt(dot.grow, frame) : 1,      // appearing and leaving are scale keys
  }));
}

// from angle and distance to screen coordinates
function dotXY(dot) {
  return {
    x: center.x + dot.dist * Math.cos(rad(dot.angle)),
    y: center.y - dot.dist * Math.sin(rad(dot.angle)), // the screen's y axis points down, hence −sin
  };
}

// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// The moving parts: one clip, plus one table holding the order.
// Bare lowercase names (clipStart, restRadius) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const linear = (t) => t; // for segments between equal values — the hold costs nothing

// one curve per segment — each the same standard as CSS cubic-bezier(), any 4 numbers you like
const popEase = cubicBezier(...popHandles);         // rest → peak
const dropEase = cubicBezier(...dropHandles);       // peak → too far
const recoverEase = cubicBezier(...recoverHandles); // too far → recover
const settleEase = cubicBezier(...settleHandles);   // end of hold → rest

const clipKeys = [ // value = radius. Each keyframe's curve belongs to the segment toward the next key
  { frame: 0,          value: restRadius,  curve: popEase },     // → pop
  { frame: peakFrame,  value: peakRadius,  curve: dropEase },    // → drop too far
  { frame: underFrame, value: underRadius, curve: recoverEase }, // → recover
  { frame: holdStart,  value: holdRadius,  curve: linear },      // → hold as long as you like
  { frame: holdEnd,    value: holdRadius,  curve: settleEase },  // → back to rest
  { frame: clipEnd,    value: restRadius },
];

// The entire "random" is this one table — 9 cells, each holding its place in line.
// fireOrder draws no random number: you scramble it once, by hand

// frame number in, 9 radii out — the player loops by taking the remainder of frame against loopFrames (1 loop)
function radiiAt(frame) {
  return fireOrder.flat().map((rank) => {
    const local = frame - clipStart - rank * stepFrames; // each replay starts later by its rank
    return keyAt(clipKeys, local);                       // fill between keys with the segment curves
  });
}

// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// Only one thing moves: the center's rotation. The sides just read it through a contact law.
// Bare lowercase names (riseStart, side) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const climbCurve = cubicBezier(...climbHandles);     // same standard as CSS cubic-bezier() — any 4 numbers you like
const descendCurve = cubicBezier(...descendHandles); // the return segment — one more curve, same standard

// the keyframes placed on the rotation: upright → the diamond → back upright after the quarter turn. Nothing else is keyed
const rotationKeys = [
  { frame: riseStart,    value: 0,            curve: climbCurve },   // → climb to the diamond
  { frame: diamondFrame, value: diamondAngle, curve: descendCurve }, // → descend to upright
  { frame: loopEnd,      value: quarterTurn },
];

// frame number in, center angle and side positions out
function squaresAt(frame) {
  const angle = keyAt(rotationKeys, frame);
  // the one-line law: a rotated square's half-width depends on the distance from the diamond
  const phi = Math.abs(((angle % quarterTurn) + quarterTurn) % quarterTurn - diamondAngle);
  const halfWidth = (side / Math.SQRT2) * Math.cos((phi * Math.PI) / 180);
  const push = Math.max(0, halfWidth - side / 2 - gap); // push while keeping the gap clearance
  return {
    center: { rotate: angle },
    left:   { x: leftHome - push },  // zero keys on the sides — the law is symmetric
    right:  { x: rightHome + push },
  };
}

// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// Only the top-left radius is keyed. The other radius is a subtraction; both centres are computed from the contact point.
// Bare lowercase names (restRadius, contact) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const shrink = cubicBezier(...shrinkHandles); // same standard as CSS cubic-bezier() — the shrink segment's curve
const grow = cubicBezier(...growHandles);     // the grow segment's curve — similar, but its own

// the keyframes placed on the radius: value = the top-left radius. This is everything that is keyed — where the keys sit is yours to choose
const radiusKeys = [
  { frame: 0,          value: restRadius, curve: shrink }, // → shrink
  { frame: midFrame,   value: midRadius,  curve: grow },   // → grow — the turnaround
  { frame: loopFrames, value: restRadius },                // back to rest — the loop seam
];

// frame number in, both centres and radii out
function circlesAt(frame) {
  const r1 = keyAt(radiusKeys, frame);      // the top-left radius
  const r2 = radiusSum - r1;                // bottom-right: zero keys — one subtraction
  const d = Math.SQRT1_2;                   // the diagonal component (= 1 / √2)
  return [
    { r: r1, x: contact - r1 * d, y: contact - r1 * d }, // recede up-left from the contact
    { r: r2, x: contact + r2 * d, y: contact + r2 * d }, // recede down-right from the contact
  ];
}

// Only one thing moves: a single rotation. Everything else re-reads it.
// Bare lowercase names (copies, delayFrames) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const ease = cubicBezier(...easeHandles); // same standard as CSS cubic-bezier() — pacing from numbers you like
const rad = (deg) => (deg / 360) * 2 * Math.PI; // degrees to radians

// placement numbers are yours too — orbit center (center), orbit radius (orbitRadius), dot radius (dotRadius).
// restAngles lists the rest angles of the 2 dots on opposite sides

// frame number in, list of circles out (loops every loopFrames frames)
function dotsAt(frame) {
  return restAngles.flatMap((rest) =>
    Array.from({ length: copies + 1 }, (_, copy) => {       // 0 = lead, then the copies
      const past = frame - copy * delayFrames;              // each copy reads slightly into the past
      const t = Math.min(Math.max(past / sweepFrames, 0), 1); // progress, clamped to 0–1
      return {
        angle: rest + 360 * ease(t),                        // one full lap
        opacity: fadePerCopy ** copy,                       // fadePerCopy× thinner per copy
      };
    })
  );
}

// Only one thing moves: a single pulse. Every shape just reads it through its own motion amounts.
// Bare lowercase names (riseStart, barW) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const ease = cubicBezier(...easeHandles); // same standard as CSS cubic-bezier() — any 4 numbers you like

// keyframes placed on the pulse: 0 → 1 → (stays 1) → 0, gaps filled by ease
const pulseKeys = [
  { frame: riseStart, value: 0, curve: ease }, // the stretch starts here
  { frame: holdStart, value: 1, curve: ease }, // fully stretched — the held pause begins
  { frame: holdEnd,   value: 1, curve: ease }, // pause over — the same curve simply runs downhill
  { frame: loopEnd,   value: 0, curve: ease }, // back to rest
];

// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// per-shape motion amounts: where it sits, and how far one pulse moves it.
// Outer bars get the bigger amounts; left and right differ only in slide's sign — the mirror is that sign
const shapes = [
  { x: outerLeftX,  w: barW,    h: barH,    growW: 0,          growH: outerGrow,  slide: -outerSlide, spin: 0        },
  { x: innerLeftX,  w: barW,    h: barH,    growW: 0,          growH: innerGrow,  slide: -innerSlide, spin: 0        },
  { x: centerX,     w: squareW, h: squareH, growW: squareGrow, growH: squareGrow, slide: 0,           spin: halfTurn },
  { x: innerRightX, w: barW,    h: barH,    growW: 0,          growH: innerGrow,  slide: innerSlide,  spin: 0        },
  { x: outerRightX, w: barW,    h: barH,    growW: 0,          growH: outerGrow,  slide: outerSlide,  spin: 0        },
];

// frame number in, placements out (loops every loopFrames)
function shapesAt(frame) {
  const pulse = keyAt(pulseKeys, frame % loopFrames);
  return shapes.map((s) => ({
    cx: s.x + s.slide * pulse,            // horizontal position — left gets minus, right gets plus
    cy: stageSize / 2,                    // vertical stays fixed — mid-canvas height
    width:  s.w + s.growW * pulse,
    height: s.h + s.growH * pulse,
    angle:  s.spin * pulse,               // only the center turns, up to halfTurn
  }));
}

// Only one thing moves: the head's progress u. 0 is the track start; 1 is a full lap.
// Bare lowercase names (whipSpan, periodFrames) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const whip = cubicBezier(...whipHandles); // same standard as CSS cubic-bezier() — the whip's face is any 4 numbers you like
const linear = (t) => t;                  // the crawl just moves straight

// The crawl is the leftover — not yours to choose
const crawlSpan = 1 - whipSpan;                      // share of the lap left for the crawl
const crawlDurFrames = periodFrames - whipDurFrames; // frames left for the crawl

// On-screen dials: a stageSize-square canvas, a stroke strokeWidth wide, a dot of radius dotRadius.
// paintHeadLag is the nudge, set by eye, that keeps the gap straddling the dot
const gapFraction = 1 - drawnFraction; // whatever the drawnFraction window leaves undrawn is the gap

// the keyframes placed on u: the whip eats whipSpan of the lap; the rest is the straight line home
const uKeys = [
  { frame: 0,             value: uAtWhipStart,            curve: whip   }, // whip start = launch spot
  { frame: whipDurFrames, value: uAtWhipStart + whipSpan, curve: linear }, // whip end
  { frame: periodFrames,  value: uAtWhipStart + 1 },                       // same spot, one lap later — not yours to choose
];

// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// frame number → head progress. Align the whip's start, whipStartFrame, to 0, then interpolate between the placed keyframes
function uAt(frame) {
  const local = ((frame - whipStartFrame) % periodFrames + periodFrames) % periodFrames;
  return keyAt(uKeys, local) % 1; // anything past 1 wraps into the next lap
}

// Only one number is animated: the progress u — 0 at rest, 1 at full separation, 2 resealed.
// Bare lowercase names (splitStart, slideMax) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not any value.
const openCurve = cubicBezier(...openHandles);   // pacing of the crack-apart beat — same standard as CSS cubic-bezier()
const closeCurve = cubicBezier(...closeHandles); // pacing of the seal-back beat

// the keyframes placed on u: 0 → 1 → 2. Up to value 1 is the way out; up to 2 is the way home. Each keyframe's curve shapes the segment to the next keyframe
const uKeys = [
  { frame: splitStart, value: 0, curve: openCurve },  // a whole circle at rest until here
  { frame: apartPeak,  value: 1, curve: closeCurve }, // full separation — the turn is only halfway
  { frame: sealEnd,    value: 2, curve: closeCurve }, // sealed — the rest is stillness
];

// fill between placed keyframes with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // at or before the first key — hold the first value
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // after the last key — hold the last value
  const next = keys.findIndex((key) => frame <= key.frame);  // index of the key we are heading toward
  const a = keys[next - 1], b = keys[next];                  // that key and the one before it bound the segment
  const t = (frame - a.frame) / (b.frame - a.frame);         // progress inside the segment, 0–1
  return a.value + (b.value - a.value) * a.curve(t);         // advance the gap along the curve
}

// frame number in, the two half-disc placements out (loops every loopFrames)
function piecesAt(frame) {
  const u = keyAt(uKeys, frame % loopFrames);
  const turn = (turnPerLoop * u) / 2;             // rotation rides u — no easing of its own, and it never reverses
  const slide = slideMax * (1 - Math.abs(1 - u)); // the slide is a hill — out, then back
  const inset = Math.min(slide, seamInset);       // the nudge into the partner — caps out fast

  // slide along the cut direction cutAngle (90 = vertical), nudge at a right angle to it
  const cut = (cutAngle * Math.PI) / 180;
  const alongX = Math.cos(cut);                   // direction along the cut
  const alongY = Math.sin(cut);
  const intoX = alongY;                           // direction half A sinks into its partner
  const intoY = -alongX;

  // build half A's offset, rotate it by the group turn, then add the center
  const shiftX = intoX * inset - alongX * slide;
  const shiftY = intoY * inset - alongY * slide;
  const g = (turn * Math.PI) / 180;
  const ax = centerX + Math.cos(g) * shiftX - Math.sin(g) * shiftY;
  const ay = centerY + Math.sin(g) * shiftX + Math.cos(g) * shiftY;

  // bulge direction = right angle to the cut + the group turn. Half B is A's point reflection
  const bulgeA = cutAngle + 90 + turn;
  return [
    { x: ax, y: ay, r: discRadius, bulge: bulgeA },
    { x: 2 * centerX - ax, y: 2 * centerY - ay, r: discRadius, bulge: bulgeA + 180 },
  ];
}

// The heart is ONE clip — gather, wait, return — replayed by eight circles riding a ring that never stops.
// Bare lowercase names (gatherSpan, ringRadius...) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not the values.
const easeIn = (t) => t * t * t; // gathering: a soft departure, accelerating into the center
const easeOutBack = (t) => {
  // returning: overshoot the seat a little, then settle. backOvershoot sets how far past
  const u = t - 1;
  return 1 + (backOvershoot + 1) * u * u * u + backOvershoot * u * u;
};

// The clip: returns the progress. 0 = home seat on the ring, 1 = dead-center. Repeats every loopFrames
function progressAt(frame) {
  const t = ((frame % loopFrames) + loopFrames) % loopFrames; // wraps even negative frames into 0〜loopFrames (delayed replays can read before the start)
  if (t < gatherSpan) return easeIn(t / gatherSpan); // gather
  if (t < gatherSpan + holdSpan) return 1; // wait at the center
  if (t < gatherSpan + holdSpan + backSpan)
    return 1 - easeOutBack((t - gatherSpan - holdSpan) / backSpan); // return
  return 0; // rest on the ring
}

// A gentle S-curve from 0 to 1 (the classic smoothstep)
const smooth = (s) => {
  const u = Math.min(1, Math.max(0, s));
  return u * u * (1 + 2 - 2 * u);
};

// Swallow level: eases to 1 over absorbWindow after landing, back to 0 over the same span on leaving
function absorbAt(frame) {
  const t = ((frame % loopFrames) + loopFrames) % loopFrames;
  return smooth((t - gatherSpan) / absorbWindow) * (1 - smooth((t - gatherSpan - holdSpan) / absorbWindow));
}

// Give it a frame number, get the middle disc and every circle's placement
function blobsAt(frame) {
  // the turning ring: evenly spaced seats, plus turnPerFrame of rotation every frame
  const ring = Array.from({ length: copyCount }, (_, i) => {
    const a = ((ringStart + turnPerFrame * frame + (360 / copyCount) * i) * Math.PI) / 180;
    return { x: centerX + ringRadius * Math.cos(a), y: centerY + ringRadius * Math.sin(a) };
  });

  // delayed replay: circle i reads the same clip staggerStep × i frames late
  const localFrames = ring.map((_, i) => frame + clipShift - i * staggerStep);

  // each circle: pull from its ring seat toward the center by the progress
  const dots = ring.map((pt, i) => {
    const p = progressAt(localFrames[i]);
    return { x: pt.x + (centerX - pt.x) * p, y: pt.y + (centerY - pt.y) * p, r: dotRadius };
  });

  // the middle disc: full radius scaled by the square root of the mean swallow level (area tracks the swallowed count)
  const share = localFrames.map((f) => absorbAt(f)).reduce((sum, a) => sum + a, 0) / copyCount;
  const coreR = coreFullRadius * Math.sqrt(share);
  const core = coreR > minVisibleRadius ? { x: centerX, y: centerY, r: coreR } : null;
  return { core, dots };
}

// The motor is one keyed swing plus a wobble its own speed creates — everything else is a re-read.
// Bare lowercase names (loopFrames, settleRate...) are numbers you pick for your own canvas —
// what this article wants you to take home is the shape, not the values.

const wrap = (value, span) => ((value % span) + span) % span;

const exitSpeed = (move) => {
  const keys = move.keys;
  const last = keys[keys.length - 1];
  const prev = keys[keys.length - 2];
  const [, , handleX, handleY] = move.eases[move.eases.length - 1]; // the last segment's easing handles
  const slope = (1 - handleY) / (1 - handleX); // the slope at the instant it leaves the key
  return (slope * (last.x - prev.x)) / (last.t - prev.t);
};

const keyedLeg = (tau, move) => { // one leg of the keyed move: find which segment the time tau sits in, ease across it
  const keys = move.keys;
  if (tau < keys[0].t) return keys[0].x; // before the move starts — rest at the start
  const seg = keys.findIndex((k, i) => i > 0 && tau < k.t); // the first key past tau
  if (seg < 0) return keys[keys.length - 1].x; // after the move ends — rest at the arrival
  const from = keys[seg - 1];
  const to = keys[seg];
  const ease = cubicBezier(...move.eases[seg - 1]);
  return from.x + (to.x - from.x) * ease((tau - from.t) / (to.t - from.t));
};

function channelAt(frame, move) { // one channel's position: the one-way swing + the speed-seeded wobble. Repeats every loopFrames
  const half = loopFrames / 2;
  const t = wrap(frame, loopFrames);
  const restA = move.keys[0].x;
  const restB = move.keys[move.keys.length - 1].x;
  const endTime = move.keys[move.keys.length - 1].t;
  const keyed = t < half ? keyedLeg(t, move) : restA + restB - keyedLeg(t - half, move); // second half = first half mirrored — author one leg and the lap closes
  const speed = exitSpeed(move);
  // wobble: a back-and-forth sine shrinking to rest; its size set by the leaving speed
  // sum both ends' arrivals (mirror flips the sign), reading one lap back for the leftover
  const arrivals = [[endTime, 1], [endTime + half, -1]];
  return arrivals.flatMap(([arrival, sign]) =>
    [0, 1].map((lap) => {
      const d = wrap(t - arrival, loopFrames) + lap * loopFrames;
      return sign * ((speed * Math.exp(-move.settleDecay * d) * Math.sin(move.settleRate * d)) / move.settleRate);
    })
  ).reduce((sum, ring) => sum + ring, keyed);
}

function glyphAt(frame) { // give a frame number, get the stem's two ends and the dot. Three channels each drive an x
  return {
    stemTop: { x: channelAt(frame, topMove), y: capTopY },
    stemBot: { x: channelAt(frame, botMove), y: capBotY },
    stemWidth,
    dot: { cx: channelAt(frame, dotMove), cy: dotCy, r: dotRadius },
  };
}

// All that moves is one vertical wave; the 7 circles each read it by their own travel.
// The bare lowercase names (periodFrames, bottomKeyFrame) are numbers you choose for
// your own screen — what this article is for is the shape, not the values.

const wrap = (value, span) => ((value % span) + span) % span;

const sharedWave = (designTime) => { // top → bottom → top; the descent and ascent carry separate curves
  const descEase = cubicBezier(...descHandles); // descent (top→bottom) easing
  const ascEase = cubicBezier(...ascHandles);   // ascent (bottom→top) easing
  const t = wrap(designTime, periodFrames);
  if (t <= bottomKeyFrame) return -1 + 2 * descEase(t / bottomKeyFrame); // top to bottom
  return 1 - 2 * ascEase((t - bottomKeyFrame) / (periodFrames - bottomKeyFrame)); // bottom to top
};

function dotsAt(frame) { // frame number → where the 7 circles go; compute the wave, read each by travel
  const wave = sharedWave(frame + capturePhase);
  return circles.map((c) => ({
    cx: c.cx,
    cy: c.mid + c.amp * wave,
    r: c.r,
  }));
}

const deg = Math.PI / 180;
const signedArc = (from, to) => ((to - from + 180) % 360 + 360) % 360 - 180;

// work out each dot's position from the two arrangements
const restRadius = restPositions.map(([x, y]) => Math.hypot(x - cx, y - cy));
const restAngle = restPositions.map(([x, y]) => Math.atan2(y - cy, x - cx) / deg);
const slotAngle = restToRing.map((slot) => ringAnglesDeg[slot]);
const angleGap = restAngle.map((a, dot) => signedArc(a, slotAngle[dot]));
const slotPoint = ringAnglesDeg.map((a) => [
  cx + ringRadius * Math.cos(a * deg),
  cy + ringRadius * Math.sin(a * deg),
]);
const back = -turntableDeg * deg;
const destLocal = restToRing.map((slot, dot) => {
  if (dot === centerDestinationDot) return [0, 0]; // the dot whose destination is the centre aims there
  const [x, y] = restPositions[ringToRest[slot]];
  const lx = x - cx;
  const ly = y - cy;
  return [lx * Math.cos(back) - ly * Math.sin(back), lx * Math.sin(back) + ly * Math.cos(back)];
});

const wrap = (frame, span) => ((frame % span) + span) % span;
const [lobeIn, lobeOut] = lobeXHandles;
const swingEase = cubicBezier(lobeIn, 0, lobeOut, 1);
const lastArrival = Math.max(...arrivals);

// first move: pull each dot in toward the centre, then fling it out to its slot (one shared bulge)
const expand = (frame, dot) => {
  const span =
    frame <= departures[dot] ? 0 : frame >= arrivals[dot] ? 1 : (frame - departures[dot]) / (arrivals[dot] - departures[dot]);
  if (dot === centerSeatDot) { // the dot resting AT the centre has no room to dip → radius eases straight out
    const radius = restRadius[dot] + swingEase(span) * (ringRadius - restRadius[dot]);
    const angle = slotAngle[dot] * deg;
    return [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
  }
  const dip = cubicBezier(lobeIn, -lobeDepths[dot], lobeOut, 1)(span);
  const radius = restRadius[dot] + dip * (ringRadius - restRadius[dot]);
  const angle = (restAngle[dot] + swingEase(span) * angleGap[dot]) * deg;
  return [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
};

// last move: one shared turn angle carries every dot from the ring toward its next seat
const turnEase = cubicBezier(...phiBezier);
const chordEase = cubicBezier(...sConBezier);
const turnAt = (frame, delay) => {
  const local = frame - delay;
  if (local <= windowStart) return 0;
  if (local >= windowEnd) return turntableDeg;
  return turntableDeg * turnEase((local - windowStart) / (windowEnd - windowStart));
};
const chordAt = (frame, delay) => {
  const local = frame - delay;
  if (local <= windowStart) return 0;
  if (local >= windowEnd) return 1;
  return chordEase((local - windowStart) / (windowEnd - windowStart));
};

function dotsAt(frame) { // frame number → where each dot goes; pick the move, read each dot
  const f = wrap(frame, periodFrames);
  return restPositions.map((_, dot) => {
    const slot = restToRing[dot];
    const delay = delaysPerSlot[slot];
    if (f <= lastArrival) { const [x, y] = expand(f, dot); return { cx: x, cy: y, r: dotRadius }; }
    if (f - delay < windowStart) return { cx: slotPoint[slot][0], cy: slotPoint[slot][1], r: dotRadius }; // middle move: hold still on the ring
    const chord = chordAt(f, delay);
    const rlx = slotPoint[slot][0] - cx;
    const rly = slotPoint[slot][1] - cy;
    const lx = rlx + chord * (destLocal[dot][0] - rlx);
    const ly = rly + chord * (destLocal[dot][1] - rly);
    const turn = turnAt(f, delay) * deg;
    return { cx: cx + lx * Math.cos(turn) - ly * Math.sin(turn), cy: cy + lx * Math.sin(turn) + ly * Math.cos(turn), r: dotRadius };
  });
}

const wrap = (value, span) => ((value % span) + span) % span;

// frame number → how far along (0 to 1). Each slide advances forward, then holds
const progressAt = (frame) => {
  const local = wrap(frame, periodFrames);
  const subcycle = Math.floor(local / subcycleFrames);
  const within = local - subcycle * subcycleFrames;
  return cubicBezier(...easeHandles)(Math.min(within / activeFrames, 1));
};

const slotCount = slotKeys.length;
const dupCount = Math.round(periodFrames / subcycleFrames);

// size for a slot. In just one of the time-shifted copies, one right-hand slot returns a different value
const valueOf = (slot, dup) => {
  if (dup === overrideDup && slot === overrideSlot) return overrideValue;
  return slot >= 0 && slot < slotCount ? slotKeys[slot] : 0;
};

function dotsAt(frame) { // frame number → each slot's position and size. One progress decides both
  const subcycle = Math.floor(wrap(frame, periodFrames) / subcycleFrames);
  const progress = progressAt(frame);
  return slotKeys.map((_, slot) => {
    const dup = wrap(subcycle + slot - (slotCount - 1), dupCount);
    return {
      coord: anchor + spacing * (slot - progress),
      value: valueOf(slot, dup) * (1 - progress) + valueOf(slot - 1, dup) * progress,
      slot,
    };
  });
}
